import{K as r,a as l,c as i,b as t,k as c,q as s,ac as h}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Excel 数据透视表、切片器与透视图","description":"从订单表建立部门产品交叉汇总，理解行列值筛选四个区域，修改汇总方式、日期分组、切片器与刷新，核对透视结果。","frontmatter":{"title":"Excel 数据透视表、切片器与透视图","description":"从订单表建立部门产品交叉汇总，理解行列值筛选四个区域，修改汇总方式、日期分组、切片器与刷新，核对透视结果。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"从订单表建立部门产品交叉汇总，理解行列值筛选四个区域，修改汇总方式、日期分组、切片器与刷新，核对透视结果。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 图表、趋势与数据表达","link":"/tools/office/excel/charts"},"next":{"text":"Excel Power Query 导入、清洗、合并与刷新","link":"/tools/office/excel/power-query"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 图表、趋势与数据表达","link":"/tools/office/excel/charts"},"next":{"text":"Excel Power Query 导入、清洗、合并与刷新","link":"/tools/office/excel/power-query"}},"headers":[],"relativePath":"tools/office/excel/pivots.md","filePath":"tools/office/excel/pivots.md"}'),n={name:"tools/office/excel/pivots.md"},k=Object.assign(n,{setup(d){const a={path:"/tools/office/excel/pivots",app:"Excel",title:"用透视表独立核对十月金额",steps:[{tab:"插入",command:"数据透视表",setting:"来源：Sales；放置：新工作表",anchor:"walkthrough-1"},{tab:"数据透视表字段窗格",command:"拖放字段",setting:"行：部门；值：金额（求和）；筛选：状态、日期",anchor:"walkthrough-2",surface:"area"},{tab:"数据透视表分析",command:"刷新",setting:"运营：2440；技术：720；总计：3160",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return l(),i("div",null,[e[0]||(e[0]=t("h1",{id:"excel-数据透视表、切片器与透视图",tabindex:"-1"},[c("Excel 数据透视表、切片器与透视图 "),t("a",{class:"header-anchor",href:"#excel-数据透视表、切片器与透视图","aria-label":'Permalink to "Excel 数据透视表、切片器与透视图"'},"​")],-1)),e[1]||(e[1]=t("p",null,"数据透视表可以不写长公式，快速改变数据的观察维度。它依赖规范明细和正确的汇总方式，不能自动修复重复订单或识别业务含义。",-1)),s(o,{guide:a}),e[2]||(e[2]=h('<h2 id="create" tabindex="-1">建立第一张透视表 <a class="header-anchor" href="#create" aria-label="Permalink to &quot;建立第一张透视表 {#create}&quot;">​</a></h2><p>先完成<a href="/tools/office/excel/start#table">Sales 订单表</a>。点击表内任意单元格，选择“插入 → 数据透视表”，确认数据源是 <code>Sales</code>，把结果放到新工作表 <code>部门透视</code>。基础练习不必勾选加入数据模型。</p><p>在字段列表中把“部门”拖到行区域，“金额”拖到值区域。应得到运营 2440、技术 1620、财务 1060，总计 5120。部门排列顺序可以不同，但数值应一致。<a href="https://support.microsoft.com/en-us/excel/get-started/create-a-pivottable-to-analyze-worksheet-data" target="_blank" rel="noopener noreferrer">微软创建透视表说明</a></p><h2 id="areas" tabindex="-1">理解四个区域 <a class="header-anchor" href="#areas" aria-label="Permalink to &quot;理解四个区域 {#areas}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>放入字段</th><th>结果</th></tr></thead><tbody><tr><td>行</td><td>部门</td><td>每个部门纵向列出</td></tr><tr><td>列</td><td>产品</td><td>产品在横向展开</td></tr><tr><td>值</td><td>金额</td><td>按行列组合汇总金额</td></tr><tr><td>筛选</td><td>状态</td><td>控制参与汇总的数据</td></tr></tbody></table><p>把产品放到列后，各行与各列的总计仍应与原始数据一致。值字段若显示“计数项：金额”，通常需要检查源列是否包含文本或空白，并通过“值字段设置”明确选择求和。单纯改成求和不代表源数据类型已经全部正确。</p><h2 id="values" tabindex="-1">数值格式与百分比 <a class="header-anchor" href="#values" aria-label="Permalink to &quot;数值格式与百分比 {#values}&quot;">​</a></h2><p>在值字段设置中选择数字格式，使刷新后更稳定地保留金额精度。想同时显示金额和占比，可把“金额”拖到值区域两次，第二个设置“值显示方式 → 总计的百分比”或合适的行列占比。</p><p>平均金额计算的是当前记录的均值，不自动等于单位平均售价。需要按数量加权时应先明确计算方式；不同指标放在同一个透视表时要标清名称和单位。</p><h2 id="filter" tabindex="-1">日期分组与切片器 <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;日期分组与切片器 {#filter}&quot;">​</a></h2><p>把日期放入行区域，右击某日期选择组合，可按年、月分组。跨年度数据不能只看月份名称而忽略年份。分组失败时检查空值、文本日期和错误值，数据模型透视表的分组行为也可能不同。</p><p>通过“数据透视表分析 → 插入切片器”选择部门或状态，即可用按钮过滤。清除筛选后应恢复完整总额。一个切片器连接多张透视表时，需要这些透视表具有兼容的数据源/缓存或模型，并在报表连接中勾选目标，不能仅因字段同名就自动联动。</p><h2 id="refresh" tabindex="-1">更新与刷新 <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;更新与刷新 {#refresh}&quot;">​</a></h2><p>在 Sales 最后一行新增测试订单，透视表不会仅凭肉眼看到新行就证明已更新。刷新透视表，检查源范围是否包含新记录；以 Excel 表格为源更容易随追加数据扩展。若数据来自 Power Query，应确认查询刷新完成后透视表使用的是最新结果。</p><p>把透视图与切片器一起放在汇总页时，保留统计口径和刷新时间说明；截图没有刷新能力，发给别人的图片只能代表导出时的状态。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>筛选状态为已完成，总计应为 4060；再限制日期为 2026 年 10 月，总计应为 3160，其中运营 2440、技术 720。和<a href="/tools/office/excel/aggregate#dates">SUMIFS 结果</a>对照，数值不一致时依次检查筛选、数据源范围、重复记录和汇总方式。</p><p>最后追加一条金额为 100 的已完成测试订单，刷新确认变化，再删除测试记录并重新刷新，恢复原始总额。</p><h2 id="walkthrough" tabindex="-1">图示跟做：用透视表独立核对十月金额 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：用透视表独立核对十月金额 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：从完整明细建立透视表 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：从完整明细建立透视表 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 数据透视表。</strong></p><p>先确认 Sales 八行订单和金额公式完整，选中任意一个表格内单元格，点击“插入 → 数据透视表”，来源应为 Sales，位置选新工作表。若看到的是固定地址，检查是否选在表内；使用表名更容易覆盖后续追加记录。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：把字段放到正确区域 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：把字段放到正确区域 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：数据透视表字段窗格 → 拖放字段。</strong></p><p>将部门拖到行，金额拖到值，状态和日期用于筛选。金额如果默认显示计数，先检查源列有无文本或空值，再打开值字段设置确认求和。筛选已完成及 2026 年 10 月日期；日期自动分组时同时检查年份，避免把不同年的十月混起来。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：改一条数据验证刷新流程 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：改一条数据验证刷新流程 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：数据透视表分析 → 刷新。</strong></p><p>确认总计 3160 后，回源表把 O004 数量改为 6，金额应为 480。返回透视表点击刷新，总计应变为 3240，运营应为 2520。恢复数量为 5，再刷新回到 3160。只看源表已改好、不刷新透视表，会交付旧的汇总结果。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>双击某个汇总数可在支持的设置下查看对应明细，适合定位差额；导出检查明细可能包含不应外发的字段。交付前清理多余检查工作表并复核数据口径。</p><p>图示操作参考：<a href="https://support.microsoft.com/zh-cn/excel/get-started/create-a-pivottable-to-analyze-worksheet-data" target="_blank" rel="noopener noreferrer">微软官方：创建、设置与刷新数据透视表</a>。核对日期：2026-11-02；界面示意与练习案例为本站独立编写。</p>',32))])}}});export{u as __pageData,k as default};
